
'use server';

import { createSupabaseServerClient } from '@/lib/supabase/server';
import { z } from 'zod';
import { v4 as uuidv4 } from 'uuid';

// Basic schema for storing the raw data from the form
const ApplicationSchema = z.object({
    type: z.string(),
    applicantName: z.string(),
    userId: z.string().min(1, "User ID must be provided."),
});

export interface ApplicationSubmissionState {
    success: boolean;
    message?: string;
    applicationId?: string;
    error?: string | null;
}

async function uploadFile(supabase: any, userId: string, file: File) {
    if (file.size === 0) return null; // Skip empty files

    const filePath = `${userId}/${uuidv4()}-${file.name}`;
    const { error: uploadError } = await supabase.storage
        .from('application_documents')
        .upload(filePath, file);

    if (uploadError) {
        throw new Error(`Storage error: ${uploadError.message}`);
    }

    const { data: publicUrlData } = supabase.storage
        .from('application_documents')
        .getPublicUrl(filePath);

    if (!publicUrlData.publicUrl) {
         throw new Error('Could not get public URL for the uploaded file.');
    }
    
    return {
        url: publicUrlData.publicUrl,
        path: filePath,
        name: file.name,
        size: file.size,
        type: file.type,
    };
}


export async function saveApplication(
    formData: FormData
): Promise<ApplicationSubmissionState> {
    const supabase = createSupabaseServerClient();

    const rawData = {
        type: formData.get('type') as string,
        applicantName: formData.get('applicantName') as string,
        userId: formData.get('userId') as string,
    };

    const validatedFields = ApplicationSchema.safeParse(rawData);

    if (!validatedFields.success) {
        return {
            success: false,
            error: 'Invalid application metadata. ' + validatedFields.error.flatten().fieldErrors,
        };
    }

    const { userId, type, applicantName } = validatedFields.data;

    try {
        let applicationData: Record<string, any> = {};

        // Process all form fields, uploading files as they are found
        for (const [key, value] of formData.entries()) {
            if (['type', 'applicantName', 'userId'].includes(key)) continue;

            const keys = key.replace(/^data\./, '').split('.'); // Remove 'data.' prefix if present
            let currentLevel = applicationData;

            for (let i = 0; i < keys.length - 1; i++) {
                currentLevel[keys[i]] = currentLevel[keys[i]] || {};
                currentLevel = currentLevel[keys[i]];
            }

            if (value instanceof File) {
                const fileInfo = await uploadFile(supabase, userId, value);
                if (fileInfo === null) continue;
                currentLevel[keys[keys.length - 1]] = fileInfo;
            } else {
                 currentLevel[keys[keys.length - 1]] = value === 'on' ? true : value;
            }
        }
        
        // Clean up empty objects that might be created by the key splitting logic
        Object.keys(applicationData).forEach(groupKey => {
            if (typeof applicationData[groupKey] === 'object' && applicationData[groupKey] !== null) {
                if (Object.keys(applicationData[groupKey]).length === 0) {
                    delete applicationData[groupKey];
                }
            }
        });

        const submissionPayload = {
            type,
            applicant_name: applicantName,
            user_id: userId,
            data: applicationData,
            status: type === 'DIN Application' ? 'Approved' : 'Pending',
        };

        const { data: insertedData, error: dbError } = await supabase
            .from('applications')
            .insert([submissionPayload])
            .select()
            .single();

        if (dbError) {
            throw dbError;
        }

        // Generate and save the custom Application ID
        const customAppId = `KSP${String(insertedData.id).padStart(3, '0')}`;
        let updatedApplicationData = { ...applicationData, applicationId: customAppId };

        // If it's a DIN application, also generate and save the DIN
        if (type === 'DIN Application') {
            const din = `DIN${String(insertedData.id).padStart(3, '0')}`;
            updatedApplicationData.din = din;

            // Also update the user's profile with the new DIN
            const { error: userUpdateError } = await supabase.auth.admin.updateUserById(
                userId,
                { user_metadata: { din: din } }
            )
            if (userUpdateError) {
                 console.error(`Failed to add DIN to user profile ${userId}:`, userUpdateError);
            }
        }
        
        // Update the application with the new custom ID and/or DIN
        const { error: appUpdateError } = await supabase
            .from('applications')
            .update({ data: updatedApplicationData })
            .eq('id', insertedData.id);

        if (appUpdateError) {
            console.error(`Failed to update application ${insertedData.id} with custom data:`, appUpdateError);
        }


        return {
            success: true,
            message: 'Application submitted successfully!',
            applicationId: insertedData.id, // Return the raw ID for redirects/internal use
        };

    } catch (error) {
        console.error('Supabase submission error:', error);
        const errorMessage = error instanceof Error 
            ? error.message
            : 'An unknown server error occurred.';
        
        return {
            success: false,
            error: `Failed to save application: ${errorMessage}`,
        };
    }
}
